css:
.dcx *{ box-sizing: border-box; }
.dcx{ margin: 0; background: #F5F7F3; }
.dcx a{ color: #0B6B3F; text-decoration: none; }
.dcx a:hover{ color: #16A85F; }
.dcx :focus-visible{ outline: 2px solid #16A85F; outline-offset: 3px; }
.dcx [data-mega]{ display: none; }
.dcx [data-navitem]:hover [data-mega],.dcx [data-mega]:hover{ display: block; }
.dcx [data-burger]{ display: none; }
@media (max-width: 1180px){.dcx [data-navlinks],.dcx [data-navlogin]{ display: none !important; }
.dcx [data-burger]{ display: inline-flex !important; }
.dcx [data-hero]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-herorail]{ grid-template-columns: minmax(0,1fr) !important; padding-right: 0 !important; }
.dcx [data-phone]{ display: none !important; }
.dcx [data-wizard]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-strip]{ grid-template-columns: repeat(3, minmax(0,1fr)) !important; }
.dcx [data-cdata]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-builder]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-buildpanes]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-chan]{ grid-template-columns: repeat(3, minmax(0,1fr)) !important; }
.dcx [data-auto]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-analytics]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-tpl]{ grid-template-columns: repeat(3, minmax(0,1fr)) !important; }
.dcx [data-ai]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-cta]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-faq]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-script]{ display: none !important; }
}
@media (max-width: 720px){.dcx [data-pad]{ padding-left: 18px !important; padding-right: 18px !important; }
.dcx [data-strip],.dcx [data-cdata],.dcx [data-chan],.dcx [data-tpl],.dcx [data-buildpanes],.dcx [data-feat3]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-h1]{ font-size: 32px !important; }
.dcx [data-h2]{ font-size: 25px !important; }
}
